'use client';

import React, { useState } from 'react';
import { PlotsProvider } from '../../context/PlotsContext';
import Navbar from '../../components/Navbar';
import Footer from '../../components/Footer';
import FloatingActions from '../../components/WhatsAppButton';
import BookSiteVisitModal from '../../components/BookSiteVisitModal';
import PropertyMatchmakerPage from '../../views/PropertyMatchmakerPage';

function PropertyFinderContent() {
  const [activePage, setActivePage] = useState('matchmaker');

  const handleNavClick = (pageId) => {
    if (pageId !== 'matchmaker') {
      window.location.href = `/?page=${pageId}`;
    } else {
      setActivePage('matchmaker');
    }
  };

  return (
    <div className="min-h-screen bg-[#0B192C] text-[#FBFBFD] flex flex-col justify-between selection:bg-[#F2B705] selection:text-[#FBFBFD]">
      <div>
        <Navbar activePage={activePage} setActivePage={handleNavClick} />
        <main className="animate-fadeIn">
          <PropertyMatchmakerPage
            setActivePage={handleNavClick}
            heading="Search plots by budget."
            intro="Filter residential plots and villas across Bengaluru's growth corridors by budget, plot size and configuration, shortlist the matches and request current pricing and site-visit slots."
          />
        </main>
      </div>
      <FloatingActions />
      <BookSiteVisitModal />
      <Footer setActivePage={handleNavClick} />
    </div>
  );
}

export default function PropertyFinderRoute() {
  return (
    <PlotsProvider>
      <PropertyFinderContent />
    </PlotsProvider>
  );
}
